"""One-line summaries of support tickets."""

import openai
from pydantic import BaseModel


class Ticket(BaseModel):
    id: int
    body: str


def summarize(ticket: Ticket) -> dict:
    response = openai.ChatCompletion.create(
        model="gpt-4o-mini",
        messages=[{"role": "user", "content": f"Summarize in one sentence: {ticket.body}"}],
    )
    return {"ticket": ticket.dict(), "summary": response["choices"][0]["message"]["content"]}
